tafsir_text:
قوله :  {  ثُمَّ لأَتِيَنَّهُم مِّن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَانِهِمْ وَعَن شَمَائِلِهِمْ } من حيث لا يشعرون {  وَلاَ تَجِدُ أَكْثَرَهُمْ شَاكِرِينَ } أي مؤمنين .

أما قوله :  {  مِّن بَيْنِ أَيْدِيهِمْ } فمن قِبَلِ الآخرة فأخبرهم أنه لا بعث بعد الموت ولا جنة ولا نار .   وأما قوله :  {  وَمِنْ خَلْفِهِمْ } فمن أمر دنياهم [ فأزينُها في أعينهم وأخبرهم ] أنه لا حساب عليهم في الآخرة فيما صنعوا في الدنيا ،   لأنهم إذا كانوا في الآخرة كانت الدنيا خلفهم .   كقوله :  {  يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ } من أمر الآخرة {  وَمَا خَلْفَهُمْ } [ البقرة : 255 ] من أمر الدنيا إذا كانت الآخرة .   وقوله :  {  وَعَنْ أَيْمَانِهِمْ } فأثبطهم عن الخير ،   كقوله :  {  إِنَّكُمْ كُنتُمْ تَأْتُونَنَا عَنِ اليَمِينِ } [ الصافات : 28 ] أي من قِبَل الخير فتثبِطوننا عنه .   وأما {  عَن شَمَائِلِهِمْ } فيعني من قبل المعاصي .   يأمرهم بمعصية الله .   {  وَلاَ تَجِدُ أَكْثَرَهُمْ شَاكِرِينَ } أي مؤمنين .   وكان ذلك ظناً منه ،   فكان الأمر على ما ظن .   كقوله :  {  وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ فَاتَّبَعُوهُ إِلاَّ فَرِيقاً مِّنَ المُؤْمِنِينَ }

[ سبأ : 20 ] أي إلا الفريق الذين آمنوا .

قوله :  {  إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ } وفيها إضمار ،   وإضمارها :  الذي خلق السماوات والأَرض وما بينهما .   وهذا موضع الإضمار .   كقوله :  {  وَلَقَدْ خَلَقْنَا السَّمَاوَاتِ وَالأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ }

[ سورة ق : 38 ] .

قوله :  {  ثُمَّ اسْتَوَى عَلَى الْعَرْشِ يُغْشِي الَّيْلَ النَّهَارَ } [ أَي أن الليل يأتي على النهار ] ويغطيه ويُذهبه {  يَطْلُبُهُ حَثِيثاً } فيذهبه {  وَالشَّمْسَ وَالقَمَرَ وَالنُّجُومَ مُسَخَّرَاتٍ بِأَمْرِهِ أَلاَ لَهُ الخَلْقُ وَالأَمْرُ تَبَارَكَ اللَّهُ } من البركة ،   وهو تفاعل {  رَبُّ العَالَمِينَ } .
